import { useState } from 'react';
import { useIssueKey, useList, useMe, useStage } from '../api/hooks';
import { useActiveChangeSet } from '../components/ActiveChangeSet';
import { Dialog, Loading, ProblemAlert, Time } from '../components/ui';
import { can } from '../roles';
import { text } from '../schema/model';

/**
 * API keys for a consumer. Keys are generated by the control plane; the key is shown once, held
 * only in this dialog's state, and dropped when the dialog closes. Stored hashes are never returned.
 */
export function Credentials({ consumerId }: { consumerId: string }) {
  const me = useMe();
  const canWrite = can(me.data?.role, 'editor');
  const active = useActiveChangeSet();
  const list = useList(`consumers/${encodeURIComponent(consumerId)}/credentials`);
  const issue = useIssueKey();
  const stage = useStage();
  const [copied, setCopied] = useState(false);
  const key = issue.data;
  const close = () => {
    issue.reset();
    setCopied(false);
  };
  return (
    <section aria-labelledby="creds-title" className="panel">
      <h2 id="creds-title">Credentials</h2>
      <p className="muted">API keys are write-only: only a salted hash is stored. Live keys are listed; new keys work
        once their change set is published.</p>
      <ProblemAlert error={list.error ?? issue.error ?? stage.error} />
      {list.isPending ? <Loading what="credentials" /> : (
        <table>
          <caption className="visually-hidden">Credentials of {consumerId}</caption>
          <thead><tr><th scope="col">ID</th><th scope="col">Type</th><th scope="col">Key ID</th>
            <th scope="col">Created</th>{canWrite && <th scope="col"><span className="visually-hidden">Actions</span></th>}</tr></thead>
          <tbody>
            {(list.data?.items ?? []).length === 0 && <tr><td colSpan={5} className="muted">No credentials.</td></tr>}
            {(list.data?.items ?? []).map((c) => (
              <tr key={c.key}>
                <th scope="row">{c.id}</th>
                <td>{text(c.spec.type)}</td>
                <td><code>{text(c.spec.keyId)}</code></td>
                <td><Time at={c.updatedAt} /></td>
                {canWrite && (
                  <td>
                    <button type="button" className="btn btn-small btn-danger" disabled={!active.id || stage.isPending}
                      onClick={() => {
                        if (active.id) {
                          stage.mutate({ path: `consumers/${encodeURIComponent(consumerId)}/credentials/${c.id}`,
                            changeSet: active.id, ifMatch: c.etag });
                        }
                      }}>Stage revoke of {c.id}</button>
                  </td>
                )}
              </tr>
            ))}
          </tbody>
        </table>
      )}
      {canWrite && (
        <button type="button" className="btn" disabled={!active.id || issue.isPending}
          onClick={() => { if (active.id) { issue.mutate({ consumerId, changeSet: active.id }); } }}>
          Generate API key
        </button>
      )}
      {stage.isSuccess && <p className="alert alert-success" role="status">Revocation staged.</p>}
      <Dialog open={key !== undefined} title="New API key" onClose={close}>
        {key && (
          <>
            <p className="alert alert-warn">Copy the key now. It is not stored and cannot be shown again.</p>
            <label htmlFor="new-api-key">API key for {consumerId}</label>
            <input id="new-api-key" className="mono" readOnly value={key.apiKey}
              onFocus={(e) => { e.target.select(); }} />
            <p className="hint">Send it in the <code>x-api-key</code> header (unless the route&apos;s key-auth config
              names another). It works once change set {key.changeSet.id} is published.</p>
            <div className="actions">
              <button type="button" className="btn btn-primary" onClick={() => {
                void navigator.clipboard.writeText(key.apiKey).then(() => { setCopied(true); });
              }}>{copied ? 'Copied' : 'Copy key'}</button>
              <button type="button" className="btn" onClick={close}>Done</button>
            </div>
            <p role="status" className="visually-hidden">{copied ? 'Key copied to the clipboard' : ''}</p>
          </>
        )}
      </Dialog>
    </section>
  );
}
